import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int tools = sc.nextInt();
        System.out.println("工具箱：" + tools + " 样");
        System.out.println("运行套装：" + (tools - 1) + " 样");
        System.out.println("念稿员：" + (tools - 2) + " 样");
        System.out.println("{c}喵");
    }
}
